[Query]
[UseOffsetPaging(DefaultPageSize = 10, MaxPageSize = 50)]
public IQueryable<Book> GetBooks([Service] AppDbContext db)
{
    return db.Books.OrderBy(b => b.Id);
}

[Query]
[UsePaging(IncludeTotalCount = true, DefaultPageSize = 10)]
public IQueryable<Book> GetBooks([Service] AppDbContext db)
{
